  ('00000000-0000-4000-8000-000000000416', 'CTX', 'CTX (resorción ósea)', 'CTX (bone resorption)', '00000000-0000-4000-8000-000000000203', '00000000-0000-4000-8000-000000000316', false),
  ('00000000-0000-4000-8000-000000000414', 'IL6', 'Interleucina-6 salival', 'Salivary interleukin-6', '00000000-0000-4000-8000-000000000206', '00000000-0000-4000-8000-000000000314', false),
  ('00000000-0000-4000-8000-000000000415', 'CORTISOL', 'Cortisol salival libre', 'Free salivary cortisol', '00000000-0000-4000-8000-000000000206', '00000000-0000-4000-8000-000000000315', false),
  ('00000000-0000-4000-8000-000000000412', 'SLEEP_H', 'Horas de sueño', 'Sleep hours', '00000000-0000-4000-8000-000000000207', '00000000-0000-4000-8000-000000000312', false),
  ('00000000-0000-4000-8000-000000000417', 'MOOD', 'Ánimo (1-5)', 'Mood (1-5)', '00000000-0000-4000-8000-000000000207', '00000000-0000-4000-8000-000000000317', false),
  ('00000000-0000-4000-8000-000000000418', 'STRESS', 'Estrés (1-5)', 'Stress (1-5)', '00000000-0000-4000-8000-000000000207', '00000000-0000-4000-8000-000000000317', false),
  ('00000000-0000-4000-8000-000000000410', 'RAD_DOSE', 'Dosis de radiación acumulada (misión)', 'Cumulative radiation dose (mission)', '00000000-0000-4000-8000-000000000204', '00000000-0000-4000-8000-000000000307', false),
  ('00000000-0000-4000-8000-000000000409', 'MUSCLE', 'Masa magra funcional', 'Functional lean mass', '00000000-0000-4000-8000-000000000203', '00000000-0000-4000-8000-000000000309', false),
  ('00000000-0000-4000-8000-000000000413', 'WBC', 'Recuento leucocitario', 'White blood cell count', '00000000-0000-4000-8000-000000000206', '00000000-0000-4000-8000-000000000313', false),
  ('00000000-0000-4000-8000-000000000411', 'PVT', 'Latencia psicomotora (PVT)', 'Psychomotor vigilance latency (PVT)', '00000000-0000-4000-8000-000000000207', '00000000-0000-4000-8000-000000000311', false),
  ('00000000-0000-4000-8000-000000000408', 'RAD_D', 'Dosis diaria de radiación', 'Daily radiation dose', '00000000-0000-4000-8000-000000000204', '00000000-0000-4000-8000-000000000310', true)
on conflict (code) do update set name_es = excluded.name_es, name_en = excluded.name_en,
  body_system_id = excluded.body_system_id, unit_id = excluded.unit_id, is_live = excluded.is_live;

-- General thresholds (user_id null).
insert into thresholds (id, indicator_id, user_id, min_critical, min_normal, max_normal, max_critical, valid_from, source, validated, mode)
select v.id, i.id, null, v.min_c, v.min_n, v.max_n, v.max_c, v.valid_from::timestamptz, v.source, v.validated, v.mode
from (values
  ('TH_HR', 'HR', 45, 55, 95, 130, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_SPO2', 'SPO2', 90, 95, 100, 100, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_SBP', 'SBP', 80, 95, 130, 155, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_DBP', 'DBP', 50, 60, 85, 100, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_RR', 'RR', 8, 12, 18, 28, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_TSKIN', 'TSKIN', -2, -0.7, 0.8, 2, '2026-01-01T00:00:00Z', 'Personal baseline: deviation (°C) from the median of the astronaut''s own skin temperature in the last 24 h (min 10 readings, src/rules/baseline.js). Deviations derived from the NASA HRP compendium range (35.8-37.3 normal, 34.5/38.5 critical, centered at 36.5). Skin temperature has no universal clinical range. TODO: validate source', false, 'baseline'),
  ('TH_BMD', 'BMD', -1.5, -1, 0.5, 2, '2026-01-01T00:00:00Z', 'NASA HRP Risk of Spaceflight-Induced Bone Changes: 1-1.5 % bone density loss per month (4-6 month missions); CSA infographic 8056: up to 1.5 %/month. Value = monthly % change.', true, 'absolute'),
  ('TH_CTX', 'CTX', 0, 0, 0.7, 1.2, '2026-01-01T00:00:00Z', 'TODO: validar fuente (estimado; depende del laboratorio, sexo y edad)', false, 'absolute'),
  ('TH_IL6', 'IL6', 0, 0.5, 5, 12, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_CORTISOL', 'CORTISOL', 2, 5, 25, 45, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_SLEEP_H', 'SLEEP_H', 4, 6.5, 9, 14, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_MOOD', 'MOOD', 1.5, 2.5, 5, 5, '2026-01-01T00:00:00Z', 'Internal 1-5 check-in scale (1 = very low). TODO: validar fuente (ej. POMS)', false, 'absolute'),
  ('TH_STRESS', 'STRESS', 1, 1, 3, 4.5, '2026-01-01T00:00:00Z', 'Internal 1-5 check-in scale (5 = very high). TODO: validar fuente', false, 'absolute'),
  ('TH_RAD_DOSE', 'RAD_DOSE', 0, 0, 400, 600, '2026-01-01T00:00:00Z', 'NASA-STD-3001 Vol.1 [V1 4030]: career effective dose < 600 mSv (NASA OCHMO Radiation Protection Technical Brief). Caution from 400 mSv is an internal app margin.', true, 'absolute'),
  ('TH_MUSCLE', 'MUSCLE', 80, 90, 105, 120, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_RAD_D', 'RAD_D', 0, 0.05, 0.8, 1.8, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_PVT', 'PVT', 150, 180, 300, 450, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute'),
  ('TH_WBC', 'WBC', 2.5, 4.5, 10.5, 15, '2026-01-01T00:00:00Z', 'General clinical reference (not from the challenge sources). Demo values. TODO: validate source', false, 'absolute')
) as v(id, code, min_c, min_n, max_n, max_c, valid_from, source, validated, mode)
join indicators i on i.code = v.code
on conflict (id) do update set min_critical = excluded.min_critical, min_normal = excluded.min_normal,
  max_normal = excluded.max_normal, max_critical = excluded.max_critical, source = excluded.source, validated = excluded.validated, mode = excluded.mode;

insert into recommendations (id, indicator_id, alert_level_id, direction, text)
select v.id, i.id, l.id, v.direction, v.text::jsonb
from (values
  ('REC_HR_LOW_CAUTION', 'HR', 'caution', 'low', '{"es":"Tu pulso está bajo (%value% %unit%). Siéntate, evita esfuerzos y vuelve a medir en 5 minutos.","en":"Your heart rate is low (%value% %unit%). Sit down, avoid exertion and measure again in 5 minutes."}'),
  ('REC_HR_LOW_CRITICAL', 'HR', 'critical', 'low', '{"es":"Pulso muy bajo (%value% %unit%). Suspende la actividad, mantente en reposo y contacta al médico de vuelo ahora.","en":"Heart rate very low (%value% %unit%). Stop activity, stay at rest and contact the flight surgeon now."}'),
  ('REC_HR_HIGH_CAUTION', 'HR', 'caution', 'high', '{"es":"Tu pulso está elevado (%value% %unit%). Haz respiración lenta 5 minutos y vuelve a medir.","en":"Your heart rate is elevated (%value% %unit%). Do slow breathing for 5 minutes and measure again."}'),
  ('REC_HR_HIGH_CRITICAL', 'HR', 'critical', 'high', '{"es":"Pulso muy alto (%value% %unit%). Detén la actividad, siéntate, respira lento y contacta al médico de vuelo ahora.","en":"Heart rate very high (%value% %unit%). Stop activity, sit down, breathe slowly and contact the flight surgeon now."}'),
  ('REC_SPO2_LOW_CAUTION', 'SPO2', 'caution', 'low', '{"es":"Tu SpO2 bajó a %value% %unit%: haz respiración profunda 5 min y vuelve a medir.","en":"Your SpO2 dropped to %value% %unit%: do deep breathing for 5 min and measure again."}'),
  ('REC_SPO2_LOW_CRITICAL', 'SPO2', 'critical', 'low', '{"es":"SpO2 crítica (%value% %unit%). Revisa la ventilación y el nivel de CO2 de la cabina, respira profundo y contacta al médico de vuelo ahora.","en":"Critical SpO2 (%value% %unit%). Check cabin ventilation and CO2 level, breathe deeply and contact the flight surgeon now."}'),
  ('REC_SBP_LOW_CAUTION', 'SBP', 'caution', 'low', '{"es":"Presión sistólica baja (%value% %unit%). Hidrátate, levántate despacio y vuelve a medir en 10 minutos.","en":"Systolic pressure low (%value% %unit%). Hydrate, stand up slowly and measure again in 10 minutes."}'),
  ('REC_SBP_LOW_CRITICAL', 'SBP', 'critical', 'low', '{"es":"Presión sistólica críticamente baja (%value% %unit%). Quédate en reposo, no hagas movimientos bruscos y contacta al médico de vuelo ahora.","en":"Systolic pressure critically low (%value% %unit%). Stay at rest, avoid sudden movements and contact the flight surgeon now."}'),
  ('REC_SBP_HIGH_CAUTION', 'SBP', 'caution', 'high', '{"es":"Presión sistólica elevada (%value% %unit%). Descansa 10 minutos, reduce la sal y vuelve a medir.","en":"Systolic pressure elevated (%value% %unit%). Rest for 10 minutes, reduce salt intake and measure again."}'),
  ('REC_SBP_HIGH_CRITICAL', 'SBP', 'critical', 'high', '{"es":"Presión sistólica críticamente alta (%value% %unit%). Detén la actividad, descansa y contacta al médico de vuelo ahora.","en":"Systolic pressure critically high (%value% %unit%). Stop activity, rest and contact the flight surgeon now."}'),
  ('REC_DBP_LOW_CAUTION', 'DBP', 'caution', 'low', '{"es":"Presión diastólica baja (%value% %unit%). Hidrátate y vuelve a medir en 10 minutos.","en":"Diastolic pressure low (%value% %unit%). Hydrate and measure again in 10 minutes."}'),
  ('REC_DBP_LOW_CRITICAL', 'DBP', 'critical', 'low', '{"es":"Presión diastólica críticamente baja (%value% %unit%). Quédate en reposo y contacta al médico de vuelo ahora.","en":"Diastolic pressure critically low (%value% %unit%). Stay at rest and contact the flight surgeon now."}'),
  ('REC_DBP_HIGH_CAUTION', 'DBP', 'caution', 'high', '{"es":"Presión diastólica elevada (%value% %unit%). Descansa 10 minutos y vuelve a medir.","en":"Diastolic pressure elevated (%value% %unit%). Rest for 10 minutes and measure again."}'),
  ('REC_DBP_HIGH_CRITICAL', 'DBP', 'critical', 'high', '{"es":"Presión diastólica críticamente alta (%value% %unit%). Detén la actividad y contacta al médico de vuelo ahora.","en":"Diastolic pressure critically high (%value% %unit%). Stop activity and contact the flight surgeon now."}'),
  ('REC_RR_LOW_CAUTION', 'RR', 'caution', 'low', '{"es":"Respiración lenta (%value% %unit%). Respira conscientemente y vuelve a medir en 5 minutos.","en":"Slow breathing (%value% %unit%). Breathe deliberately and measure again in 5 minutes."}'),
  ('REC_RR_LOW_CRITICAL', 'RR', 'critical', 'low', '{"es":"Respiración muy lenta (%value% %unit%). Contacta al médico de vuelo ahora y revisa la calidad del aire de la cabina.","en":"Breathing very slow (%value% %unit%). Contact the flight surgeon now and check cabin air quality."}'),
  ('REC_RR_HIGH_CAUTION', 'RR', 'caution', 'high', '{"es":"Respiración rápida (%value% %unit%). Haz respiración lenta y vuelve a medir en 5 minutos.","en":"Fast breathing (%value% %unit%). Do slow breathing and measure again in 5 minutes."}'),
  ('REC_RR_HIGH_CRITICAL', 'RR', 'critical', 'high', '{"es":"Respiración muy rápida (%value% %unit%). Revisa el CO2 de la cabina, descansa y contacta al médico de vuelo ahora.","en":"Breathing very fast (%value% %unit%). Check cabin CO2, rest and contact the flight surgeon now."}'),
  ('REC_TSKIN_LOW_CAUTION', 'TSKIN', 'caution', 'low', '{"es":"Tu temperatura de piel bajó respecto a tu valor habitual (%value% %unit%). Abrígate, verifica la temperatura de la cabina y vuelve a medir en 15 minutos.","en":"Your skin temperature dropped below your usual value (%value% %unit%). Warm up, check the cabin temperature and measure again in 15 minutes."}'),
  ('REC_TSKIN_LOW_CRITICAL', 'TSKIN', 'critical', 'low', '{"es":"Tu temperatura de piel bajó mucho respecto a tu valor habitual (%value% %unit%): posible enfriamiento. Abrígate de inmediato, mide tu temperatura corporal y contacta al médico de vuelo.","en":"Your skin temperature dropped far below your usual value (%value% %unit%): possible chilling. Warm up immediately, measure your body temperature and contact the flight surgeon."}'),
  ('REC_TSKIN_HIGH_CAUTION', 'TSKIN', 'caution', 'high', '{"es":"Tu temperatura de piel subió respecto a tu valor habitual (%value% %unit%). Reduce la actividad, hidrátate, verifica la temperatura de la cabina y vuelve a medir en 15 minutos.","en":"Your skin temperature rose above your usual value (%value% %unit%). Reduce activity, hydrate, check the cabin temperature and measure again in 15 minutes."}'),
  ('REC_TSKIN_HIGH_CRITICAL', 'TSKIN', 'critical', 'high', '{"es":"Tu temperatura de piel subió mucho respecto a tu valor habitual (%value% %unit%): posible fiebre. Detén la actividad, mide tu temperatura corporal y contacta al médico de vuelo ahora.","en":"Your skin temperature rose far above your usual value (%value% %unit%): possible fever. Stop activity, measure your body temperature and contact the flight surgeon now."}'),
  ('REC_BMD_LOW_CAUTION', 'BMD', 'caution', 'low', '{"es":"Pérdida ósea de %value% %unit%, mayor a la esperada. Cumple tu ejercicio de resistencia y revisa tu plan con el médico de vuelo.","en":"Bone loss of %value% %unit%, higher than expected. Complete your resistance exercise and review your plan with the flight surgeon."}'),
  ('REC_BMD_LOW_CRITICAL', 'BMD', 'critical', 'low', '{"es":"Pérdida ósea muy acelerada (%value% %unit%). Contacta al médico de vuelo para revisar tu ejercicio de resistencia y la posible medicación (bifosfonatos).","en":"Very fast bone loss (%value% %unit%). Contact the flight surgeon to review your resistance exercise and possible medication (bisphosphonates)."}'),
  ('REC_CTX_HIGH_CAUTION', 'CTX', 'caution', 'high', '{"es":"Marcador de resorción ósea elevado (%value% %unit%). Cumple tu ejercicio de resistencia y avisa al médico de vuelo en tu próximo reporte.","en":"Bone resorption marker elevated (%value% %unit%). Keep up resistance exercise and tell the flight surgeon in your next report."}'),
  ('REC_CTX_HIGH_CRITICAL', 'CTX', 'critical', 'high', '{"es":"Resorción ósea muy elevada (%value% %unit%). Contacta al médico de vuelo para revisar tu plan de ejercicio y nutrición.","en":"Bone resorption very high (%value% %unit%). Contact the flight surgeon to review your exercise and nutrition plan."}'),
  ('REC_IL6_HIGH_CAUTION', 'IL6', 'caution', 'high', '{"es":"Marcador de inflamación elevado (IL-6 %value% %unit%). Prioriza el descanso, hidrátate y revisa si tienes síntomas.","en":"Inflammation marker elevated (IL-6 %value% %unit%). Prioritize rest, hydrate and check for symptoms."}'),
  ('REC_IL6_HIGH_CRITICAL', 'IL6', 'critical', 'high', '{"es":"Inflamación muy elevada (IL-6 %value% %unit%). Contacta al médico de vuelo ahora y reporta tus síntomas.","en":"Inflammation very high (IL-6 %value% %unit%). Contact the flight surgeon now and report your symptoms."}'),
  ('REC_CORTISOL_LOW_CAUTION', 'CORTISOL', 'caution', 'low', '{"es":"Cortisol bajo (%value% %unit%). Cuida tu descanso y alimentación, y avisa al médico de vuelo en tu próximo reporte.","en":"Cortisol low (%value% %unit%). Look after your rest and nutrition, and tell the flight surgeon in your next report."}'),
  ('REC_CORTISOL_LOW_CRITICAL', 'CORTISOL', 'critical', 'low', '{"es":"Cortisol muy bajo (%value% %unit%). Contacta al médico de vuelo ahora.","en":"Cortisol very low (%value% %unit%). Contact the flight surgeon now."}'),
  ('REC_CORTISOL_HIGH_CAUTION', 'CORTISOL', 'caution', 'high', '{"es":"Cortisol elevado (%value% %unit%), señal de estrés. Haz una pausa de relajación y revisa tu horario de sueño.","en":"Cortisol elevated (%value% %unit%), a sign of stress. Take a relaxation break and review your sleep schedule."}'),
  ('REC_CORTISOL_HIGH_CRITICAL', 'CORTISOL', 'critical', 'high', '{"es":"Cortisol muy elevado (%value% %unit%). Contacta al médico de vuelo y reduce tu carga de trabajo hoy.","en":"Cortisol very high (%value% %unit%). Contact the flight surgeon and reduce your workload today."}'),
  ('REC_SLEEP_H_LOW_CAUTION', 'SLEEP_H', 'caution', 'low', '{"es":"Dormiste poco (%value% h). Reduce la luz y el ruido antes de dormir, respeta el horario de descanso y usa la iluminación LED de cabina que simula el ciclo día/noche.","en":"You slept little (%value% h). Reduce light and noise before bed, keep to the rest schedule and use the cabin LED lighting that simulates the day/night cycle."}'),
  ('REC_SLEEP_H_LOW_CRITICAL', 'SLEEP_H', 'critical', 'low', '{"es":"Sueño muy insuficiente (%value% h). Evita tareas de alto riesgo hoy y avisa al médico de vuelo.","en":"Severely insufficient sleep (%value% h). Avoid high-risk tasks today and tell the flight surgeon."}'),
  ('REC_SLEEP_H_HIGH_CAUTION', 'SLEEP_H', 'caution', 'high', '{"es":"Dormiste mucho (%value% h). Mantén horarios regulares y haz algo de actividad física hoy.","en":"You slept a lot (%value% h). Keep regular hours and do some physical activity today."}'),
  ('REC_SLEEP_H_HIGH_CRITICAL', 'SLEEP_H', 'critical', 'high', '{"es":"Sueño excesivo (%value% h). Avisa al médico de vuelo, puede indicar fatiga o problemas de ánimo.","en":"Excessive sleep (%value% h). Tell the flight surgeon, it may indicate fatigue or mood issues."}'),
  ('REC_MOOD_LOW_CAUTION', 'MOOD', 'caution', 'low', '{"es":"Tu ánimo está bajo. Habla con un compañero o con tu familia y haz una actividad que disfrutes.","en":"Your mood is low. Talk to a crewmate or your family and do an activity you enjoy."}'),
  ('REC_MOOD_LOW_CRITICAL', 'MOOD', 'critical', 'low', '{"es":"Tu ánimo está muy bajo. Contacta al médico de vuelo o al oficial médico de la tripulación hoy.","en":"Your mood is very low. Contact the flight surgeon or the crew medical officer today."}'),
  ('REC_STRESS_HIGH_CAUTION', 'STRESS', 'caution', 'high', '{"es":"Tu estrés está elevado. Haz 5 minutos de respiración guiada y una pausa de las tareas.","en":"Your stress is elevated. Do 5 minutes of guided breathing and take a break from tasks."}'),
  ('REC_STRESS_HIGH_CRITICAL', 'STRESS', 'critical', 'high', '{"es":"Tu estrés es muy alto. Contacta al médico de vuelo y pide apoyo para reducir tu carga de trabajo.","en":"Your stress is very high. Contact the flight surgeon and ask for support to reduce your workload."}'),
  ('REC_RAD_DOSE_HIGH_CAUTION', 'RAD_DOSE', 'caution', 'high', '{"es":"Dosis acumulada de radiación alta (%value% %unit%). Limita el tiempo fuera de las zonas con más blindaje y revisa el plan de exposición.","en":"Cumulative radiation dose high (%value% %unit%). Limit time outside better-shielded areas and review the exposure plan."}'),
  ('REC_RAD_DOSE_HIGH_CRITICAL', 'RAD_DOSE', 'critical', 'high', '{"es":"Dosis acumulada en el límite de carrera (%value% %unit%). Refúgiate en la zona más blindada y contacta al médico de vuelo ahora.","en":"Cumulative dose at the career limit (%value% %unit%). Shelter in the most shielded area and contact the flight surgeon now."}'),
  ('REC_BMD_HIGH_CAUTION', 'BMD', 'caution', 'high', '{"es":"Cambio óseo inusual (%value% %unit%). Repite la medición para descartar un error del equipo y avisa al médico de vuelo.","en":"Unusual bone change (%value% %unit%). Repeat the measurement to rule out an equipment error and tell the flight surgeon."}'),
  ('REC_BMD_HIGH_CRITICAL', 'BMD', 'critical', 'high', '{"es":"Cambio óseo fuera de lo esperable (%value% %unit%). Repite la medición y contacta al médico de vuelo.","en":"Bone change outside the expected range (%value% %unit%). Repeat the measurement and contact the flight surgeon."}'),
  ('REC_MUSCLE_LOW_CAUTION', 'MUSCLE', 'caution', 'low', '{"es":"Tu masa muscular bajó a %value% %unit%. Completa tu ejercicio de resistencia del día y cuida tu alimentación.","en":"Your muscle mass dropped to %value% %unit%. Complete today''s resistance exercise and watch your nutrition."}'),
  ('REC_MUSCLE_LOW_CRITICAL', 'MUSCLE', 'critical', 'low', '{"es":"Pérdida muscular importante (%value% %unit%). Contacta al médico de vuelo para ajustar tu ejercicio y nutrición.","en":"Significant muscle loss (%value% %unit%). Contact the flight surgeon to adjust your exercise and nutrition."}'),
  ('REC_MUSCLE_HIGH_CAUTION', 'MUSCLE', 'caution', 'high', '{"es":"Valor por encima de lo esperado (%value% %unit%): puede ser retención de líquidos o un error de medición. Repite la medición.","en":"Value above expected (%value% %unit%): it may be fluid retention or a measurement error. Repeat the measurement."}'),
  ('REC_MUSCLE_HIGH_CRITICAL', 'MUSCLE', 'critical', 'high', '{"es":"Valor muy por encima de lo esperado (%value% %unit%). Repite la medición y avisa al médico de vuelo.","en":"Value far above expected (%value% %unit%). Repeat the measurement and tell the flight surgeon."}'),
  ('REC_IL6_LOW_CAUTION', 'IL6', 'caution', 'low', '{"es":"IL-6 salival más baja de lo habitual (%value% %unit%). Repite la muestra y avisa al médico de vuelo en tu próximo reporte.","en":"Salivary IL-6 lower than usual (%value% %unit%). Repeat the sample and tell the flight surgeon in your next report."}'),
  ('REC_WBC_LOW_CAUTION', 'WBC', 'caution', 'low', '{"es":"Leucocitos bajos (%value% %unit%): defensas disminuidas. Refuerza la higiene, descansa y avisa al médico de vuelo.","en":"Low white blood cells (%value% %unit%): reduced defenses. Reinforce hygiene, rest and tell the flight surgeon."}'),
  ('REC_WBC_LOW_CRITICAL', 'WBC', 'critical', 'low', '{"es":"Leucocitos muy bajos (%value% %unit%). Contacta al médico de vuelo ahora y evita el contacto cercano con tripulantes enfermos.","en":"Very low white blood cells (%value% %unit%). Contact the flight surgeon now and avoid close contact with sick crewmates."}'),
  ('REC_WBC_HIGH_CAUTION', 'WBC', 'caution', 'high', '{"es":"Leucocitos elevados (%value% %unit%): posible infección. Revisa fiebre y síntomas y avisa al médico de vuelo.","en":"Elevated white blood cells (%value% %unit%): possible infection. Check for fever and symptoms and tell the flight surgeon."}'),
  ('REC_WBC_HIGH_CRITICAL', 'WBC', 'critical', 'high', '{"es":"Leucocitos muy elevados (%value% %unit%): posible infección aguda. Contacta al médico de vuelo ahora.","en":"Very high white blood cells (%value% %unit%): possible acute infection. Contact the flight surgeon now."}'),
  ('REC_PVT_LOW_CAUTION', 'PVT', 'caution', 'low', '{"es":"Tu tiempo de reacción fue inusualmente corto (%value% %unit%). Repite la prueba con calma: puede ser una respuesta anticipada.","en":"Your reaction time was unusually short (%value% %unit%). Repeat the test calmly: it may be an anticipated response."}'),
  ('REC_PVT_LOW_CRITICAL', 'PVT', 'critical', 'low', '{"es":"Tiempo de reacción fuera de lo humanamente esperable (%value% %unit%). Repite la prueba; si se repite, avisa al médico de vuelo.","en":"Reaction time outside the humanly expected range (%value% %unit%). Repeat the test; if it repeats, tell the flight surgeon."}'),
  ('REC_PVT_HIGH_CAUTION', 'PVT', 'caution', 'high', '{"es":"Tu tiempo de reacción subió a %value% %unit%: señal de fatiga. Descansa y evita tareas críticas hasta recuperarte.","en":"Your reaction time rose to %value% %unit%: a sign of fatigue. Rest and avoid critical tasks until you recover."}'),
  ('REC_PVT_HIGH_CRITICAL', 'PVT', 'critical', 'high', '{"es":"Fatiga severa (%value% %unit%). Suspende las tareas críticas, descansa y contacta al médico de vuelo ahora.","en":"Severe fatigue (%value% %unit%). Stop critical tasks, rest and contact the flight surgeon now."}'),
  ('REC_RAD_D_LOW_CAUTION', 'RAD_D', 'caution', 'low', '{"es":"El dosímetro marca una dosis diaria muy baja (%value% %unit%). Verifica que esté conectado y transmitiendo.","en":"The dosimeter shows a very low daily dose (%value% %unit%). Check that it is connected and transmitting."}'),
  ('REC_RAD_D_HIGH_CAUTION', 'RAD_D', 'caution', 'high', '{"es":"Dosis diaria de radiación elevada (%value% %unit%). Permanece en las zonas con más blindaje y revisa el plan de exposición.","en":"Daily radiation dose elevated (%value% %unit%). Stay in the best-shielded areas and review the exposure plan."}'),
  ('REC_RAD_D_HIGH_CRITICAL', 'RAD_D', 'critical', 'high', '{"es":"Dosis diaria muy alta (%value% %unit%): posible evento solar. Refúgiate de inmediato en la zona más blindada y contacta al médico de vuelo.","en":"Daily dose very high (%value% %unit%): possible solar event. Shelter immediately in the most shielded area and contact the flight surgeon."}')
) as v(id, code, level_code, direction, text)
join indicators i on i.code = v.code
join alert_levels l on l.code = v.level_code
on conflict (id) do update set indicator_id = excluded.indicator_id, alert_level_id = excluded.alert_level_id,
  direction = excluded.direction, text = excluded.text;

